package com.stockshield.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="order_events",indexes=@Index(name="idx_event_order",columnList="orderId")) public class OrderEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long orderId; @Column(nullable=false) private String eventType; @Column(nullable=false,length=1000) private String message; @Column(nullable=false) private Instant createdAt=Instant.now(); public OrderEvent(){} public OrderEvent(Long o,String t,String m){orderId=o;eventType=t;message=m;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public String getEventType(){return eventType;} public String getMessage(){return message;} public Instant getCreatedAt(){return createdAt;}}
